import{z as A,x as i,o,c as l,q as n,j as E,D as a,d as r,s as d,S as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Seed-1.6","description":"","frontmatter":{"title":"Seed-1.6","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/seed-1-6.md","filePath":"llm/seed-1-6.md","lastUpdated":1791413859000}'),B={name:"llm/seed-1-6.md"};function T(p,e,C,g,h,D){const t=i("Mermaid");return o(),l("div",null,[e[2]||(e[2]=n('<h1 id="seed-1-6" tabindex="-1">Seed-1.6 <a class="header-anchor" href="#seed-1-6" aria-label="Permalink to &quot;Seed-1.6&quot;">​</a></h1><div class="epigraph"><p>AdaCoT 按题目难度决定要不要想；RL 里用新的奖励惩罚过度思考、奖励恰如其分的思考，而不是把每道题都写成数万 token。</p><footer>—— ByteDance Seed，Introduction to Techniques Used in Seed1.6，2025-06-25</footer></div><p><a href="/llm/seed-doubao">Seed / 豆包</a> 专文按产品线把 Thinking-v1.5、1.5-VL、1.6 博客与 OSS-36B 列在同一张地图上。本篇只写 <strong>Seed1.6</strong>：官方技术博客（不是完整 arXiv 总报告）里已经钉死的稀疏 MoE 规格、三段续预训练、以及后训练拆成的 <strong>Thinking / Adaptive CoT</strong> 两条。不要用 1.6 的 230B 去填未披露的 Seed2.0，也不要把方舟 API 名写成可下载权重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>R1 类模型证明长链能买竞赛分，也证明<strong>过度思考</strong>会把简单题变成延迟税。Seed 要同时做通用助手、视觉理解、GUI 与 256K 文档，不能把「永远 FullCoT」当成默认产品。需要一种后训练，让策略按题决定是否展开思维，并且让用户仍能用提示钉死 FullCoT 或 NoCoT。</p><p><span class="marginnote">「过度思考」就是给「1+1 等于几」也写三页草稿：答案没错，但用户多等十几秒、服务多烧成千上万 token——这就是文中所说的延迟税。AdaCoT 的目标正是让模型自己判断哪些题配得上长草稿。</span></p><p>第二条约束是模态。1.5 的 VL 是另一份报告；1.6 要把视觉能力做进<strong>同一条预训练课程</strong>，而不是只在对话期加投影。否则高考卷、JEE 卷上的图题会变成「纯文本推理模型假装看见图」。</p><h3 id="博客不是层表" tabindex="-1">博客不是层表 <a class="header-anchor" href="#博客不是层表" aria-label="Permalink to &quot;博客不是层表&quot;">​</a></h3><p>1.6 未公开专家数、路由公式、RL 系数与 AdaCoT 奖励的精确式。能写的是博客给出的阶段名、激活/总参、窗口、三种推理模式，以及团队自己报的触发率与高考 / JEE 实验设定。缺的数字保持「未公开」。</p><p><span class="marginnote">体验入口博客写明 <code>doubao-seed-1-6-250615</code> 与 thinking 变体。集成必须钉日期后缀；「豆包最新」不可复现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>预训练。</strong> 沿用 Seed1.5 的稀疏 MoE 结论：<strong>23B 激活、230B 总参</strong>。三段续训：（1）纯文本：网页、书、论文、代码；规则 + 模型清洗、过滤、去重、采样。（2）<strong>MMCT</strong>（Multimodal Mixed Continual Training）：提高学科、代码、推理密度，并混入高质量视觉，与文本联合训。（3）<strong>LongCT</strong>：按长度区间把最大序列从 32K 抬到 <strong>256K</strong>。博客称同参数量级上 Base 相对 Seed1.5 Base 明显抬升，具体格以文中表为准（外部对照取自 Qwen 技术报告口径）。</p><p><span class="marginnote">「23B 激活、230B 总参」可以类比成一家 2300 人的公司，每道题只请得起约 230 人的专家小组：总人数决定知识储备，当班人数决定每道题的电费与速度。这就是稀疏 MoE「总参撑知识、激活撑吞吐」的直觉。</span></p><p><strong>后训练两条。</strong> Seed1.6-Thinking：工序类似 Seed1.5-Thinking，多阶段拒绝采样微调（RFT）与 RL 交替，每一轮 RL 从上一轮 RFT 结束处接着训，用多维奖励模型在 RFT 过滤后的候选里选最优。数据含数学、代码、谜题与非推理样本，并并入 VLM 能力。相对 1.5-Thinking，公开叙事是更大训练算力与更高质量集。Seed1.6（Adaptive CoT）在此之上用 <strong>AdaCoT</strong> 压思维长度。</p><p><strong>AdaCoT 三模式。</strong> FullCoT：每题先想，效果对齐 Thinking，但链更短。NoCoT：直接答。AdaCoT：按提示自动决定是否想。实现靠 RL 中的奖励：<strong>惩罚过度思考、奖励适当思考</strong>。用户可用提示配置模式。博客报 AdaCoT 在简单任务 MMLU 上触发率约 <strong>37%</strong>，中等 MMLU-Pro 约 <strong>70%</strong>，AIME / BeyondAIME 约 <strong>90%–100%</strong>，难任务上与 FullCoT 效果相当。多模态场景同样有效。</p><h3 id="无训练的并行解码与两场考试" tabindex="-1">无训练的并行解码与两场考试 <a class="header-anchor" href="#无训练的并行解码与两场考试" aria-label="Permalink to &quot;无训练的并行解码与两场考试&quot;">​</a></h3><p>Thinking 在推理期用<strong>并行解码</strong>（training-free）在作答前展开更多思维 token。博客称在超难集 BeyondAIME 上约 +8 分，代码任务也有增益。这是测试时计算，不是改 MoE。</p><p>泛化评测用 2025 山东高考（国标语文数学英语 + 省卷其它科，满分 750）与 JEE Advanced。高考：客观题机评后人工复核，开放题两名高中阅卷教师匿名多轮；<strong>无 prompt 工程</strong>，题面来自网上原卷。DeepSeek R1 只吃文本，其它模型吃图文。英语听力一律满分假设。理科 Seed1.6-Thinking 648（后用更高清生物化学图复测到 676），文科 683。JEE：题面以图像输入，每题采样 5 次，按官方正误与倒扣。团队称 Gemini-2.5-Pro 与 Seed1.6-Thinking 若当作考生可进入印度前十量级；Seed 数学五次采样全对。这些是<strong>内部评测协议</strong>，不是高考官方成绩。</p>',18)),(o(),E(s,null,{default:a(()=>[d(t,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%2223B%2F230B%20MoE%20%E5%9F%BA%E5%BA%A7%22%5D%20--%3E%20T%5B%22%E7%BA%AF%E6%96%87%E6%9C%AC%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20T%20--%3E%20M%5B%22MMCT%EF%BC%9A%E6%96%87%E6%9C%AC%2B%E8%A7%86%E8%A7%89%22%5D%0A%20%20M%20--%3E%20L%5B%22LongCT%EF%BC%9A32K%E2%86%92256K%22%5D%0A%20%20L%20--%3E%20TH%5B%221.6-Thinking%EF%BC%9ARFT%E2%86%94RL%22%5D%0A%20%20L%20--%3E%20AD%5B%221.6%20AdaCoT%EF%BC%9A%E6%83%A9%E7%BD%9A%E8%BF%87%E5%BA%A6%E6%80%9D%E8%80%83%22%5D%0A%20%20TH%20--%3E%20PD%5B%22%E6%8E%A8%E7%90%86%E6%9C%9F%E5%B9%B6%E8%A1%8C%E8%A7%A3%E7%A0%81%22%5D%0A%20%20AD%20--%3E%20MOD%5B%22FullCoT%20%2F%20NoCoT%20%2F%20AdaCoT%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AdaCoT 把「思考开关」从产品按钮部分内化成<strong>条件策略</strong>。触发率随难度上升，说明奖励没有把长度本身当成目标，而是把「该想的题想够、不该想的题缩短」写进标量。这与 R1-Zero 只优化终点正确率、因而长度单调涨，是相反的产品约束。FullCoT 仍保留长链能力，证明压缩不是把教师搜到的程序删掉，而是学会何时调用。</p><p>MMCT 把视觉放进续预训练，使图文题与文本题共享同一套表示更新，而不是后加适配器。高考化学生物对模糊图敏感、提高分辨率后理科再涨约 30 分，是这条机制的存在性证据：缺像素时「多模态」名不副实。</p><p><span class="marginnote">BeyondAIME 是 Seed-Thinking-v1.5 起就用的内部超难集。外部复现若没有该集，不能声称复现了 1.6 的数学配方，只能对公开 AIME / GPQA 说话。</span></p><h3 id="并行解码不是-adacot" tabindex="-1">并行解码不是 AdaCoT <a class="header-anchor" href="#并行解码不是-adacot" aria-label="Permalink to &quot;并行解码不是 AdaCoT&quot;">​</a></h3><p>并行解码在已经会想的 Thinking 模型上加测试时宽度；AdaCoT 在训练期教策略<strong>少想</strong>。二者可以叠，但博客把它们分给不同变体。服务上 FullCoT 与 AdaCoT 是不同 API 行为，不要用 Thinking 的 BeyondAIME +8 去宣传 AdaCoT 的省 token。</p>',6)),(o(),E(s,null,{default:a(()=>[d(t,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E9%81%93%E6%96%B0%E9%A2%98%E8%BF%9B%E6%9D%A5%22%5D%20--%3E%20ADA%5B%22AdaCoT%EF%BC%9A%E4%BC%B0%E8%AE%A1%E9%9A%BE%E5%BA%A6%22%5D%0A%20%20ADA%20--%3E%7C%22%E7%AE%80%E5%8D%95%E9%A2%98%EF%BC%9A%E8%A7%A6%E5%8F%91%E7%8E%87%E7%BA%A6%2037%25%22%7C%20SHORT%5B%22NoCoT%EF%BC%9A%E7%9B%B4%E6%8E%A5%E7%AD%94%EF%BC%8C%E7%9C%81%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20ADA%20--%3E%7C%22%E4%B8%AD%E7%AD%89%E9%A2%98%EF%BC%9A%E7%BA%A6%2070%25%22%7C%20MID%5B%22%E7%9F%AD%E9%93%BE%E6%80%9D%E8%80%83%22%5D%0A%20%20ADA%20--%3E%7C%22%E9%9A%BE%E9%A2%98%EF%BC%9A90%25%20%E4%BB%A5%E4%B8%8A%22%7C%20FULL%5B%22%E6%8E%A5%E8%BF%91%20FullCoT%20%E9%95%BF%E9%93%BE%22%5D%0A%20%20Q%20--%3E%20PD%5B%22Thinking%20%E5%8F%98%E4%BD%93%E5%8F%A6%E7%94%A8%E5%B9%B6%E8%A1%8C%E8%A7%A3%E7%A0%81%22%5D%0A%20%20PD%20--%3E%20WIDE%5B%22%E4%BD%9C%E7%AD%94%E5%89%8D%E5%B1%95%E5%BC%80%E5%A4%9A%E8%B7%AF%E6%80%9D%E7%BB%B4%E5%8A%A0%E5%AE%BD%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>闭源。路由、共享专家、RL 超参、AdaCoT 奖励公式均未公开。方舟上的 <code>doubao-seed-1-6-*</code> 与 C 端豆包还有检索与安全层，API 裸模型对不上 App。Seed-OSS-36B 是另一条 Apache 稠密 512K 线，与 1.6 的 256K MoE <strong>不是</strong>同一检查点。</p><p>高考 / JEE 数字绑定题源、是否喂图、听力满分假设与人工阅卷；换一套扫描件会动。不要把 648/683 写成「官方高考分数」。R1-0528 在该内部设定里吃纯文本，与多模态对照不公平，博客已注明。</p><p><span class="marginnote">初学者容易把「理科 648」当成高考官方成绩。实际是团队拿真题当考卷、自设阅卷与喂图协议的内部实验：换一套扫描清晰度、去掉听力满分假设，分数就会动，不能写成「模型考上了某大学」。</span></p><p><span class="marginnote">写 Seed 只引用 seed.bytedance.com 与官方方舟文档。聚合站上的单价与 Elo 不是本篇出处。</span></p><h3 id="何时不必用-1-6" tabindex="-1">何时不必用 1.6 <a class="header-anchor" href="#何时不必用-1-6" aria-label="Permalink to &quot;何时不必用 1.6&quot;">​</a></h3><p>只要开源可复现 RL，走 R1 / DAPO 权重与论文。只要纯文本竞赛、且能接受永远长链，0528 的公开表更硬。需要 512K 本地稠密，用 OSS-36B，不要幻想 1.6 会开源 230B。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Seed1.6：公开规格 23B 激活 / 230B 总参，预训练经 MMCT 与 LongCT 到 256K，全周期融合视觉。</li><li>后训练拆 Thinking（长链 + 可选并行解码）与 AdaCoT（Full / No / 自适应三模式）。</li><li>AdaCoT 用 RL 奖励抑制过度思考；触发率随难度从约 37% 升到 90%+。</li><li>高考与 JEE 是团队内部泛化实验，协议与是否喂图必须一起引用。</li><li>出处：ByteDance Seed，<em>Introduction to Techniques Used in Seed1.6</em>，2025-06-25；产品地图见 <a href="/llm/seed-doubao">Seed / 豆包</a>。</li></ul>',9))])}const m=A(B,[["render",T]]);export{u as __pageData,m as default};
